            elif tag in ('+', '-'):
                left_val = evaluate(node[0])
                right_val = evaluate(node[2])

                if op == '+':
                    return left_val + right_val
                else:  # -
                    return left_val - right_val

        raise SyntaxError(f"Bilinmeyen AST düğümü: {node}")

    ast = parse_primary()
    return evaluate(ast)


def calistir(program: str):
    """Programı çalıştır ve son ifadenin değerini döndür."""
    # Tokenize et
    tokens = tokenize(program)

    # Boş program kontrolü
    if not tokens:
        return None

    # Parse et ve değerlendir
    ast = parse(tokens)
    result = evaluate(ast)

    return result
